function empiricalCdf(samples, x){ var c=0; for(var i=0;i<samples.length;i++){ if(samples[i]<=x) c++; } return c/samples.length; }
function ksStatistic(cdf, samples){
  var sorted=samples.slice().sort(function(a,b){return a-b;});
  var n=sorted.length, D=0;
  for(var i=0;i<n;i++){ var F=cdf(sorted[i]); var Femp=(i+1)/n;
    D=Math.max(D, Math.abs(Femp-F), Math.abs(F-i/n)); }
  return D;
}
function ksPValue(D, n){ var x=Math.sqrt(n)*D; var s=0; for(var j=1;j<=100;j++){ s+=Math.pow(-1,j-1)*Math.exp(-2*j*j*x*x); } return 2*s; }
var EXPORTS={empiricalCdf:empiricalCdf, ksStatistic:ksStatistic, ksPValue:ksPValue};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.KolmogorovSmirnovForgePure = EXPORTS; }
